package com.bank.buggycollect;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class RaceDemo {
    private static final Logger log = Logger.getLogger("Race");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> source = IntStream.range(0, 100_000).boxed().toList();
        BuggyCollectService service = new BuggyCollectService();

        // run a few times — size is often NOT 100000, or it may throw
        for (int run = 1; run <= 3; run++) {
            int finalRun = run;
            try {
                int size = service.buggyCollect(source).size();
                log.warning(() -> "run " + finalRun + " → size=" + size
                    + " (expected 100000; race corrupts it)");
            } catch (Exception ex) {
                log.severe(() -> "run " + finalRun + " → threw " + ex.getClass().getSimpleName());
            }
        }
    }
}

// ─── Would be in service/BuggyCollectService.java ───
class BuggyCollectService {
    // BUG: shared non-thread-safe ArrayList mutated from parallel forEach
    List<Integer> buggyCollect(List<Integer> source) {
        List<Integer> results = new ArrayList<>();      // NOT thread-safe
        source.parallelStream()
            .filter(n -> n % 2 == 0)
            .forEach(results::add);                       // DATA RACE: concurrent add
        return results;
    }
}
